// ============================================================
// InvestorBase -> GHL contact mapping.
//
// Zapier's exact payload shape is unknown until the first real fire, so key
// matching is deliberately tolerant (case/space/punctuation-insensitive with
// aliases) and every unrecognised key is REPORTED back rather than dropped
// silently. The first live test tells us the real field names.
// ============================================================
const defs = ($('Fetch Field Definitions').first().json.customFields) || [];
const ID = {};
for (const d of defs) ID[d.name] = d.id;

const body = $('IB Buyers Webhook').first().json.body || $('IB Buyers Webhook').first().json || {};

// Zapier may send one buyer, an array, or an object wrapping an array.
let rows = [];
if (Array.isArray(body)) rows = body;
else if (Array.isArray(body.buyers)) rows = body.buyers;
else if (Array.isArray(body.items)) rows = body.items;
else if (Array.isArray(body.data)) rows = body.data;
else rows = [body];

const norm = (s) => String(s == null ? '' : s).toLowerCase().replace(/[^a-z0-9]/g, '');
const pick = (row, aliases) => {
  const map = {};
  for (const k of Object.keys(row)) map[norm(k)] = row[k];
  for (const a of aliases) {
    const v = map[norm(a)];
    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
  }
  return '';
};
const num = (v) => { const n = Number(String(v).replace(/[^0-9.\-]/g, '')); return isFinite(n) ? n : null; };

// A joined list ('9876543210,9876543210') means the Zap mapped this field from
// the TRIGGER instead of the Loop step, so every iteration carries every
// buyer's number. Deliberately do NOT silently take the first one - that would
// give all 84 contacts the same phone number and look like it worked.
// Fail loudly instead.
const isJoined = (p) => {
  const s = String(p || '');
  return (s.indexOf(',') !== -1 || s.indexOf(';') !== -1) &&
         s.replace(/\D/g, '').length > 11;
};
const phoneFmt = (p) => {
  if (isJoined(p)) return '';
  const d = String(p || '').replace(/\D/g, '');
  const t = (d.length === 11 && d[0] === '1') ? d.slice(1) : d;
  return t.length === 10 ? '+1' + t : '';
};

// Tier from LinkedDeal count. The >200 cap is not optional: the profiled
// sample maxed at 23,078 linked deals against a 994 average - those are
// iBuyers, title companies and data artifacts, not local flippers.
const band = (n) => {
  if (n == null) return { tier: '', institutional: false, review: false };
  if (n > 200) return { tier: '', institutional: true, review: false };
  if (n >= 50)  return { tier: 'A', institutional: false, review: true };
  if (n >= 15)  return { tier: 'A', institutional: false, review: false };
  if (n >= 5)   return { tier: 'B', institutional: false, review: false };
  return { tier: 'C', institutional: false, review: false };
};

const KNOWN = ['entity name','entityname','company','registered entity','registered entity name','linkeddeal','last sale date','last sale price','subject address','subject_address','property address','deal address','searched deal address','smart match','buyer status','touchpoint status','state','units count','prior sale date','purchase price per square foot','address','phone 1','phone 2','wireless 2','wireless2','first name','firstname','last name','lastname',
  'wireless 1','wireless1','phone','mobile','cell','beta: possible email','possible email','email',
  'buyer type','buyertype','property type','propertytype','city','property city','zip','property zip',
  'bedrooms','beds','bathrooms','baths','sqft','square feet','building sqft',
  'most recent sale price','recent sale price','prior sale price','previous sale price',
  'most recent sale date','recent sale date','linkeddeal count','linked deals','linkeddeals','deals',
  'buyer mailing address','mailing address','buyer mailing city','mailing city',
  'buyer mailing state','mailing state','buyer mailing zip','mailing zip'];
const knownSet = new Set(KNOWN.map(norm));

const out = [];
const skipped = [];
const unmappedKeys = new Set();

for (const row of rows) {
  if (!row || typeof row !== 'object') continue;
  for (const k of Object.keys(row)) if (!knownSet.has(norm(k))) unmappedKeys.add(k);

  const first = pick(row, ['First Name', 'firstname', 'first']);
  const last  = pick(row, ['Last Name', 'lastname', 'last']);
  const entity = pick(row, ['Registered Entity', 'Registered Entity Name', 'Entity Name', 'entityname', 'Company']);
  const phone1 = phoneFmt(pick(row, ['Phone 1', 'Wireless 1', 'wireless1', 'Phone', 'Mobile', 'Cell']));
  const phone2 = phoneFmt(pick(row, ['Phone 2', 'Wireless 2', 'wireless2']));
  const phone = phone1 || phone2;
  const email = pick(row, ['Beta: Possible Email', 'Possible Email', 'Email']);
  const name = [first, last].filter(Boolean).join(' ') || entity || '(no name)';

  if (!phone) {
    const raw1 = pick(row, ['Phone 1', 'Wireless 1', 'wireless1', 'Phone', 'Mobile', 'Cell']);
    const raw2 = pick(row, ['Phone 2', 'Wireless 2', 'wireless2']);
    const why = (isJoined(raw1) || isJoined(raw2))
      ? 'MAPPING ERROR: phone arrived as a joined list (' + String(raw1).slice(0, 40) +
        '). In the Zap, map Phone 1/Phone 2 from the LOOP step, not the trigger.'
      : 'no usable wireless number';
    skipped.push({ name, why });
    continue;
  }

  const deals = num(pick(row, ['LinkedDeal', 'LinkedDeal count', 'Linked Deals', 'linkeddeals', 'Deals']));
  const b = band(deals);

  const buyerType = norm(pick(row, ['Buyer Type', 'buyertype']));
  const types = [];
  if (b.institutional) types.push('Institutional');
  if (buyerType.indexOf('flip') !== -1) types.push('Flipper');
  if (buyerType.indexOf('landlord') !== -1 || buyerType.indexOf('rental') !== -1) types.push('Landlord');

  const propType = norm(pick(row, ['Property Type', 'propertytype']));
  const propTypes = [];
  if (propType.indexOf('single') !== -1 || propType === 'sfr') propTypes.push('SFR');
  if (propType.indexOf('land') !== -1) propTypes.push('Land');
  if (propType.indexOf('condo') !== -1) propTypes.push('Condo');

  const recent = num(pick(row, ['Last Sale Price', 'Most Recent Sale Price', 'Recent Sale Price']));
  const prior  = num(pick(row, ['Prior Sale Price', 'Previous Sale Price']));
  const prices = [recent, prior].filter(v => v != null && v > 0);

  const cf = [];
  const add = (fieldName, value) => {
    if (value === '' || value === null || value === undefined) return;
    if (Array.isArray(value) && !value.length) return;
    if (ID[fieldName]) cf.push({ id: ID[fieldName], fieldValue: value });
  };

  // Which deal this list was pulled for. InvestorBase returns buyers within
  // ~2 miles of the subject, so this is the geographic cross-reference.
  // Taken from the payload if Zapier sends it, else the row itself.
  const subject = pick(row, ['Searched Deal Address', 'Subject Address', 'subject_address', 'Property Address', 'Deal Address'])
                  || String(body.subject_address || body.subjectAddress || body.property_address || '').trim();
  if (subject && ID['buy_ib_property']) cf.push({ id: ID['buy_ib_property'], fieldValue: subject, _ibProperty: true });

  add('record_type', ['Buyer']);
  add('buy_source', ['InvestorBase']);
  add('buy_status', 'Active');
  if (b.tier) add('buy_tier', b.tier);
  if (types.length) add('buy_type', types);
  if (propTypes.length) add('buy_prop_types', propTypes);
  if (entity) add('buy_entity_name', entity);
  if (deals != null) add('buy_deals_count', String(deals));
  const zip = pick(row, ['Zip', 'Property Zip']);
  if (zip) add('buy_zips', zip);
  if (prices.length) { add('buy_price_min', String(Math.min.apply(null, prices)));
                       add('buy_price_max', String(Math.max.apply(null, prices))); }
  const beds = num(pick(row, ['Bedrooms', 'Beds']));   if (beds != null) add('buy_beds_typ', String(beds));
  const baths = num(pick(row, ['Bathrooms', 'Baths'])); if (baths != null) add('buy_baths_typ', String(baths));
  const sqft = num(pick(row, ['Sqft', 'Square Feet', 'Building Sqft'])); if (sqft != null) add('buy_sqft_typ', String(sqft));
  const lastSale = pick(row, ['Last Sale Date', 'Most Recent Sale Date', 'Recent Sale Date']);
  if (lastSale) add('buy_last_purchase', lastSale);

  // Consent record stays FACTUAL: skip-traced, never opted in.
  add('buy_consent_status', 'Not Opted In');
  if (phone2 && phone2 !== phone) add('buy_notes_phone2', phone2);

  // NO blanket hold. Every imported buyer is blast-eligible by default - that
  // is the point of buying the list. The scrub REMOVES litigators and DNC hits;
  // it does not gate everyone else.
  //
  // Sole carve-out: >200 linked deals. Those are iBuyers, title companies and
  // data artifacts (the profiled sample maxed at 23,078 against a 994 average),
  // not local flippers - texting them is pure waste. Clear excl_all_blasts on
  // the contact if you want them included.
  if (b.institutional) {
    add('excl_all_blasts', 'Yes');
    add('excl_notes', 'INSTITUTIONAL - ' + deals + ' linked deals (iBuyer/title/data artifact), not a local buyer. Clear this field to include them.');
  }

  const notes = ['Imported from InvestorBase.'];
  if (deals != null) notes.push('LinkedDeal count: ' + deals + '.');
  if (b.review) notes.push('50-200 deals - manual review recommended.');
  if (b.institutional) notes.push('Over 200 deals - flagged institutional, excluded from calling.');
  if (email) notes.push('Email is InvestorBase beta/low-confidence - do not cold-blast it.');
  add('buy_notes', notes.join(' '));

  out.push({ json: {
    contact: {
      locationId: 'ib5jEnyqqq06FIEqlVGs',
      firstName: first || undefined,
      lastName: last || undefined,
      name: (!first && !last) ? name : undefined,
      phone,
      email: email || undefined,
      companyName: entity || undefined,
      address1: pick(row, ['Buyer Mailing Address', 'Mailing Address']) || undefined,
      city: pick(row, ['Buyer Mailing City', 'Mailing City']) || undefined,
      state: pick(row, ['Buyer Mailing State', 'Mailing State']) || undefined,
      postalCode: pick(row, ['Buyer Mailing Zip', 'Mailing Zip']) || undefined,
      source: 'InvestorBase',
      customFields: cf
    },
    _meta: { name, phone, deals, tier: b.tier || (b.institutional ? 'INSTITUTIONAL' : 'none'),
             review: b.review, institutional: b.institutional }
  } });
}

if (!out.length) {
  return [{ json: { contact: null, _meta: null, _report: {
    received: rows.length, mapped: 0, skipped,
    unmappedKeys: Array.from(unmappedKeys),
    note: 'Nothing mapped. Check unmappedKeys against the aliases in this node.'
  } } }];
}

out[0].json._report = { received: rows.length, mapped: out.length, skipped,
                        unmappedKeys: Array.from(unmappedKeys) };
return out;

// Summarise the import. Upsert dedupes on phone/email per the location's
// settings, so re-importing the same list updates rather than duplicates.
const results = $input.all();
const meta = $('Map InvestorBase Rows').all();
const report = (meta[0] && meta[0].json._report) || { received: 0, mapped: 0, skipped: [], unmappedKeys: [] };

const created = [], updated = [], failed = [];
for (let i = 0; i < results.length; i++) {
  const r = results[i].json || {};
  const m = (meta[i] && meta[i].json._meta) || {};
  const row = { name: m.name, phone: m.phone, deals: m.deals, tier: m.tier };
  if (r.contact && r.contact.id) {
    row.id = r.contact.id;
    (r.new ? created : updated).push(row);
  } else {
    row.error = (r.message || r.error || 'unknown').toString().slice(0, 200);
    failed.push(row);
  }
}

const institutional = meta.filter(m => m.json._meta && m.json._meta.institutional).length;
const review = meta.filter(m => m.json._meta && m.json._meta.review).length;

return [{ json: {
  status: 'IMPORT COMPLETE - buyers are blast-eligible',
  received: report.received,
  mapped: report.mapped,
  created: created.length,
  updated: updated.length,
  failed: failed.length,
  skipped_no_phone: (report.skipped || []).length,
  flagged_institutional: institutional,
  flagged_manual_review: review,
  blast_eligible: created.length + updated.length - institutional,
  scrub_note: 'Imported buyers are blast-eligible immediately. Only litigator/DNC hits should be excluded - run the scrub and set excl_all_blasts=Yes on those. buy_scrub_date is still empty until a scrub runs.',
  unmapped_source_keys: report.unmappedKeys,
  created_rows: created,
  updated_rows: updated,
  failed_rows: failed,
  skipped_rows: report.skipped
} }];

// ============================================================
// MERGE POLICY — the import may only ever ADD information.
//
// The join key is the PHONE NUMBER, normalised to +1XXXXXXXXXX upstream.
// Names are never matched on: "Marlon Pierre" / "Marlon R. Pierre" /
// "PIERRE HOLDINGS LLC" cannot be told apart from three different people, and
// a wrong merge is unrecoverable while a duplicate is merely annoying.
//
// When the phone DOES match an existing buyer, InvestorBase data is treated as
// the weaker source, because it is skip-traced and was never confirmed with
// anyone. Concretely, an import must never be able to:
//   - move a BH Main buyer into the cold segment (buy_source is UNIONed)
//   - strip Buyer off a record_type a human curated (UNIONed)
//   - overwrite a hand-set VIP tier with a LinkedDeal band (kept)
//   - resurrect a DNC or Blacklist buyer as Active (kept, always)
//   - clear an excl_ rule a human set after talking to them (kept)
// ============================================================
const defs = ($('Fetch Field Definitions').first().json.customFields) || [];
const ID = {}, NAME = {};
for (const d of defs) { ID[d.name] = d.id; NAME[d.id] = d.name; }

const mapped = $('Map InvestorBase Rows').all();
const lookups = $input.all();

// InvestorBase repeats the searched address per buyer, so a value mapped from
// the trigger arrives as the same string joined to itself. Collapse that.
const dedupeRepeat = (s) => {
  const t = String(s || '').trim();
  if (!t) return '';
  for (let k = 2; k <= 12; k++) {
    if (t.length % k !== 0) continue;
    const part = t.slice(0, t.length / k).replace(/,\s*$/, '').trim();
    if (!part) continue;
    if (Array(k).fill(part).join(', ') === t) return part;
  }
  return t;
};

// ---- policy tables, keyed on field NAME ----
// Both sides are true at once: a buyer really is on the master list AND was
// returned by an InvestorBase pull. Losing either one loses a segment.
const UNION = new Set(['buy_source', 'record_type', 'buy_type', 'buy_prop_types']);
// A human decided these. Skip-traced data does not get to argue.
const KEEP = new Set([
  'buy_status', 'buy_tier',
  'excl_all_blasts', 'excl_notes', 'excl_verified_date',
  'excl_below_price', 'excl_above_price', 'excl_below_sqft',
  'excl_prop_types', 'excl_outside_counties', 'excl_outside_neighborhoods'
]);
const APPEND = new Set(['buy_notes']);
// Everything else — the buy box, beds, zips, sale history — fills blanks only.

const asArr = (v) => v == null ? []
  : Array.isArray(v) ? v.map(x => String(x).trim()).filter(Boolean)
  : String(v).split(/[;,]/).map(s => s.trim()).filter(Boolean);
const isBlank = (v) => v == null || v === '' || (Array.isArray(v) && !v.length);
const keyOf = (s) => String(s).toLowerCase().replace(/[^a-z0-9]/g, '');

const out = [];
const merges = [];

for (let i = 0; i < mapped.length; i++) {
  const item = mapped[i].json;
  if (!item || !item.contact) continue;
  const contact = JSON.parse(JSON.stringify(item.contact));

  const existing = (lookups[i] && lookups[i].json && lookups[i].json.contact) || null;

  // ---- buy_ib_property: append-only list of every address this buyer was
  // sourced for. A buyer legitimately turns up in many pulls over time.
  const IB_FIELD = (contact.customFields || []).find(f => f._ibProperty);
  let ibValue = dedupeRepeat(IB_FIELD ? IB_FIELD.fieldValue : '');

  if (!existing) {
    // Brand new buyer: nothing to protect, write it as mapped.
    contact.customFields = (contact.customFields || [])
      .map(f => f._ibProperty ? { id: f.id, fieldValue: ibValue } : f)
      .filter(f => f.fieldValue !== '' || !f._ibProperty);
    out.push({ json: Object.assign({}, item, { contact, _merge: { existing: false } }) });
    continue;
  }

  // ---- existing buyer: read what they already have, by field name ----
  const prior = {};
  for (const f of (existing.customFields || [])) {
    const nm = NAME[f.id];
    if (nm) prior[nm] = f.value;
  }

  if (ibValue) {
    const lines = String(prior['buy_ib_property'] || '').split(/[;\n]/).map(s => s.trim()).filter(Boolean);
    const seen = new Set(lines.map(keyOf));
    if (!seen.has(keyOf(ibValue))) lines.push(ibValue);
    // buy_ib_property is a single-line TEXT field in GHL and the type cannot be
  // changed after creation. Newlines would survive the API but render as one
  // unreadable run-on in the contact card, and any human who edits the field
  // would flatten the list. Semicolons display correctly and read back the same.
  ibValue = lines.join('; ');
  }

  const kept = [], unioned = [];
  const merged = [];

  for (const f of (contact.customFields || [])) {
    if (f._ibProperty) {
      if (ibValue) merged.push({ id: f.id, fieldValue: ibValue });
      continue;
    }
    const nm = NAME[f.id];
    if (!nm) { merged.push(f); continue; }
    const was = prior[nm];

    if (UNION.has(nm)) {
      const seen = new Set(), union = [];
      for (const v of asArr(was).concat(asArr(f.fieldValue))) {
        const k = keyOf(v);
        if (k && !seen.has(k)) { seen.add(k); union.push(v); }
      }
      if (union.length) merged.push({ id: f.id, fieldValue: union });
      if (asArr(was).length && union.length > asArr(was).length) unioned.push(nm);
      continue;
    }

    if (KEEP.has(nm) && !isBlank(was)) { kept.push(nm); continue; }

    if (APPEND.has(nm)) {
      const before = String(was || '').trim();
      const add = String(f.fieldValue || '').trim();
      if (!add) continue;
      merged.push({ id: f.id, fieldValue: before && before.indexOf(add) === -1 ? before + ' ' + add : (before || add) });
      continue;
    }

    // Default: fill blanks only. Curated data outranks a skip-trace guess.
    if (isBlank(was)) merged.push(f);
    else kept.push(nm);
  }

  contact.customFields = merged;

  // ---- top-level fields: same rule. Never overwrite a curated name, email,
  // company or original source with skip-traced values.
  for (const k of ['firstName', 'lastName', 'name', 'email', 'companyName',
                   'address1', 'city', 'state', 'postalCode', 'source']) {
    if (contact[k] !== undefined && !isBlank(existing[k])) { delete contact[k]; kept.push(k); }
  }

  merges.push({ name: item._meta ? item._meta.name : '', phone: contact.phone,
                contactId: existing.id, kept: kept, unioned: unioned });

  out.push({ json: Object.assign({}, item, {
    contact,
    _merge: { existing: true, contactId: existing.id, kept: kept, unioned: unioned }
  }) });
}

if (!out.length) {
  return [{ json: { contact: null, _meta: null,
                    _report: { received: 0, mapped: 0, skipped: [], unmappedKeys: [] } } }];
}
// Carried to the summary so the run says how many were merged vs created.
out[0].json._merges = merges;
return out;
